input.sparql:
SELECT ?zone ?zname ?tempPoint ?spPoint WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zname }
  ?zone brick:hasTemperature ?tempPoint .
  ?zone brick:hasSetpoint ?sp .
  ?sp brick:isSetpointFor ?tempPoint .
  ?sp a brick:CoolingSetpoint .
  BIND(?sp AS ?spPoint)
}

